const RB4=[
["Mittag","Jägerschnitzel mit Kartoffeln und Mischgemüse",520,45,"30 Min.",["150 g Schweineschnitzel","250 g Kartoffeln","150 g Mischgemüse (TK)","80 g Champignons","125 ml Jägersoße (½ Päckchen Fix)","5 g Öl","Salz, Pfeffer"],"Kartoffeln schälen und in Salzwasser 20 Min. kochen.\nJägersoße nach Packung anrühren, Champignons in Scheiben darin 5 Min. köcheln.\nMischgemüse in wenig Wasser 6–8 Min. garen, salzen.\nSchnitzel flach klopfen, salzen, pfeffern und im Öl je Seite 3 Min. braten.\nSchnitzel mit Soße, Kartoffeln und Gemüse anrichten.","h"],
["Mittag","Bratreis",610,32,"20 Min.",["70 g Reis (trocken, am besten vom Vortag gekocht)","2 Eier (M)","100 g Erbsen und Möhren (TK)","50 g Kochschinkenwürfel","1 Frühlingszwiebel","10 g Öl","1 EL Sojasoße","Salz, Pfeffer"],"Reis kochen und abkühlen lassen (oder Reis vom Vortag nehmen).\nÖl in einer großen Pfanne erhitzen, Erbsen, Möhren und Schinken 3 Min. braten.\nReis zugeben und 4–5 Min. kräftig mitbraten.\nEier an den Rand schlagen, verrühren, stocken lassen und unter den Reis mischen.\nMit Sojasoße, Pfeffer und Frühlingszwiebel-Ringen abschmecken.","h"],
["Mittag","Kaiserschmarren",670,24,"20 Min.",["60 g Mehl","2 Eier (M)","125 ml Milch 1,5 %","10 g Zucker","1 Prise Salz","10 g Butter","15 g Rosinen (optional)","1 TL Puderzucker","100 g Apfelmus"],"Eier trennen. Mehl, Milch, Eigelb und Salz glatt rühren.\nEiweiß mit dem Zucker steif schlagen und locker unterheben.\nButter in einer Pfanne schmelzen, Teig hineingießen, Rosinen darüberstreuen und bei mittlerer Hitze 4 Min. backen.\nWenden, mit zwei Gabeln in Stücke reißen und 2–3 Min. fertig braten.\nMit Puderzucker bestäuben und mit Apfelmus servieren.","s"],
["Mittag","Currywurst mit Currysoße und Kartoffeln",550,18,"25 Min.",["1 Bockwurst (100 g)","80 ml Currysoße (z. B. Maggi)","250 g Kartoffeln","1 TL Currypulver","Salz"],"Kartoffeln in Salzwasser 20 Min. kochen (oder als Ofenkartoffeln backen).\nBockwurst in heißem, nicht kochendem Wasser 8 Min. ziehen lassen.\nCurrysoße erwärmen.\nWurst in Stücke schneiden, mit Soße übergießen, mit Currypulver bestäuben und mit den Kartoffeln servieren.","h"],
["Mittag","Milchreis",540,15,"30 Min.",["70 g Milchreis (trocken)","300 ml Milch 1,5 %","10 g Zucker","1 Prise Salz","1 TL Zimt-Zucker","100 g Apfelmus oder Kirschen"],"Milch mit Zucker und Salz aufkochen, Milchreis einrühren.\nBei kleiner Hitze mit Deckel 25–30 Min. quellen lassen, öfter umrühren.\nMit Zimt-Zucker und Apfelmus oder Kirschen servieren.","s"],
["Mittag","Geflügel-Geschnetzeltes mit Reis",645,44,"25 Min.",["150 g Hähnchen- oder Putenbrust","70 g Reis (trocken)","½ Zwiebel","100 g Paprika","75 ml Kochsahne 15 %","100 ml Gemüsebrühe","1 TL Speisestärke","5 g Öl","Paprikapulver, Salz, Pfeffer"],"Reis nach Packung kochen.\nFleisch in Streifen schneiden, würzen und im Öl rundum 4 Min. scharf anbraten, herausnehmen.\nZwiebel und Paprika würfeln und in derselben Pfanne 3 Min. braten.\nMit Brühe und Sahne ablöschen, Stärke in etwas Wasser anrühren und einrühren, kurz aufkochen.\nFleisch zurück in die Soße geben, 2 Min. ziehen lassen und mit dem Reis servieren.","h"],
["Abend","Kartoffel-Feta-Hack-Auflauf",745,43,"15 Min. + 35 Min. Ofen",["300 g Kartoffeln","125 g Rinderhack","50 g Feta","½ Zwiebel","100 g passierte Tomaten","50 ml Kochsahne 15 %","Paprikapulver, Oregano, Salz, Pfeffer"],"Ofen auf 200 °C (Umluft 180 °C) vorheizen.\nKartoffeln schälen, in dünne Scheiben schneiden und 5 Min. in Salzwasser vorkochen.\nHack mit gewürfelter Zwiebel krümelig braten, mit Tomaten, Paprikapulver, Oregano, Salz und Pfeffer würzen.\nKartoffeln und Hack abwechselnd in eine Auflaufform schichten, Sahne darübergießen.\nFeta darüberbröseln und 30–35 Min. backen, bis die Kartoffeln weich sind.","h"]];
