const RB6=[
["Frühstück","Bircher-Müsli mit Apfel und Joghurt",422,14,"5 Min. + über Nacht",["40 g Haferflocken","100 ml Milch 1,5 %","100 g Naturjoghurt 1,5 %","1 Apfel","10 g Walnüsse","1 TL Honig (7 g)","Zimt"],"Haferflocken mit Milch und Joghurt verrühren und abgedeckt über Nacht in den Kühlschrank stellen.\nMorgens den Apfel grob raspeln und unterrühren.\nMit Zimt und Honig abschmecken, gehackte Walnüsse darüberstreuen.","s"],
["Frühstück","Quark-Pfannkuchen mit Apfelmus",368,24,"15 Min.",["30 g Weizenmehl","1 Ei (M)","100 g Magerquark","50 ml Milch 1,5 %","5 g Öl","100 g Apfelmus ohne Zucker","Zimt, 1 Prise Salz"],"Mehl, Ei, Quark, Milch, Salz und etwas Zimt zu einem dicken Teig verrühren.\nÖl in einer beschichteten Pfanne erhitzen und 3–4 kleine Pfannkuchen je Seite 2–3 Min. goldbraun backen.\nMit Apfelmus und einer Prise Zimt servieren.","s"],
["Frühstück","Chia-Mango-Joghurt",312,13,"5 Min. + 15 Min. quellen",["15 g Chiasamen","150 g Naturjoghurt 1,5 %","100 ml Milch 1,5 %","100 g Mango","10 g Kokosraspel"],"Chiasamen mit Milch verrühren, nach 5 Min. nochmal umrühren und mind. 15 Min. (oder über Nacht) quellen lassen.\nJoghurt unterrühren.\nMango würfeln und mit den Kokosraspeln darübergeben.","s"],
["Frühstück","Schoko-Porridge mit Himbeeren",426,27,"8 Min.",["50 g Haferflocken","200 ml Milch 1,5 %","5 g Backkakao (1 TL)","100 g Himbeeren (TK geht)","100 g Skyr natur","1 TL Honig (7 g)"],"Haferflocken mit Milch und Kakao aufkochen und 3–4 Min. unter Rühren köcheln.\nVom Herd nehmen, Skyr und Honig unterrühren.\nHimbeeren darübergeben (TK-Beeren kurz in der Mikrowelle antauen).","s"],
["Frühstück","Joghurt-Quark-Becher mit Kiwi und Müsli",367,22,"5 Min.",["150 g Naturjoghurt 1,5 %","100 g Magerquark","30 g Müsli ohne Zucker","2 Kiwi","1 TL Honig (7 g)"],"Joghurt, Quark und Honig glatt rühren.\nKiwis schälen und würfeln.\nAbwechselnd Quarkcreme, Kiwi und Müsli in ein Glas schichten.","s"],
["Frühstück","Ricotta-Toast mit Erdbeeren und Honig",312,12,"5 Min.",["60 g Vollkorntoast (2 Scheiben)","60 g Ricotta","150 g Erdbeeren","1 TL Honig (7 g)","Minze (optional)"],"Toast rösten.\nRicotta darauf verstreichen.\nErdbeeren in Scheiben schneiden, darauflegen, mit Honig beträufeln und nach Wunsch mit Minze bestreuen.","s"],
["Frühstück","Kokos-Ananas-Porridge",447,24,"8 Min.",["50 g Haferflocken","150 ml Milch 1,5 %","50 ml Kokosmilch light","100 g Ananas","100 g Skyr natur","5 g Kokosraspel"],"Haferflocken mit Milch und Kokosmilch aufkochen und 3–4 Min. köcheln.\nVom Herd nehmen und den Skyr unterrühren.\nAnanas würfeln und mit den Kokosraspeln darübergeben.","s"],
["Frühstück","Dattel-Zimt-Overnight-Oats",408,18,"5 Min. + über Nacht",["50 g Haferflocken","150 ml Milch 1,5 %","100 g Naturjoghurt 1,5 %","2 Datteln","10 g Mandeln","Zimt"],"Datteln entsteinen und klein hacken.\nHaferflocken, Milch, Joghurt, Datteln und Zimt verrühren und über Nacht kühlen.\nMorgens mit gehackten Mandeln bestreuen.","s"],
["Frühstück","Erdbeer-Bananen-Smoothie mit Hafer",368,21,"5 Min.",["150 g Erdbeeren (TK geht)","1 Banane","150 ml Milch 1,5 %","100 g Skyr natur","20 g Haferflocken"],"Alle Zutaten in den Mixer geben.\nFein pürieren, bei Bedarf mit etwas Wasser verdünnen.\nSofort trinken.","s"],
["Frühstück","Hüttenkäse-Pfirsich-Bowl",414,30,"5 Min.",["200 g Hüttenkäse","1 Pfirsich oder Nektarine","20 g Müsli ohne Zucker","10 g Mandeln","1 TL Honig (7 g)"],"Hüttenkäse in eine Schale geben.\nPfirsich in Spalten schneiden und darauflegen.\nMit Müsli und gehackten Mandeln bestreuen und mit Honig beträufeln.","s"],
["Frühstück","Spinat-Feta-Omelett mit Vollkornbrot",386,25,"10 Min.",["2 Eier (M)","50 g Babyspinat","30 g Feta","3 g Öl","50 g Vollkornbrot (1 Scheibe)","Salz, Pfeffer"],"Eier mit Salz und Pfeffer verquirlen.\nSpinat im Öl 1 Min. zusammenfallen lassen, Eier darübergießen.\nFeta darüberbröseln und bei kleiner Hitze mit Deckel 3–4 Min. stocken lassen.\nMit dem Brot servieren.","h"],
["Frühstück","Herzhaftes Porridge mit Spiegelei",342,19,"10 Min.",["50 g Haferflocken","200 ml Gemüsebrühe","50 g Babyspinat","1 Ei (M)","10 g vegetarischer Hartkäse (Parmesan-Art)","3 g Öl","Pfeffer, Chiliflocken"],"Haferflocken in der Brühe 3–4 Min. köcheln, Spinat unterrühren.\nIn der Zwischenzeit das Ei im Öl als Spiegelei braten.\nPorridge mit Hartkäse und Pfeffer abschmecken, Spiegelei darauflegen und mit Chiliflocken bestreuen.","h"],
["Frühstück","Tomaten-Mozzarella-Brot",388,19,"5 Min.",["100 g Vollkornbrot (2 Scheiben)","60 g Mozzarella","1 Tomate","Basilikum, Balsamico, Salz, Pfeffer"],"Tomate und Mozzarella in Scheiben schneiden.\nAbwechselnd auf das Brot legen.\nMit Salz, Pfeffer, ein paar Tropfen Balsamico und Basilikum würzen.","h"],
["Frühstück","Rührei-Wrap mit Paprika",460,26,"10 Min.",["1 Vollkorn-Tortilla","2 Eier (M)","½ Paprika","20 g Gouda","3 g Öl","Salz, Pfeffer"],"Paprika fein würfeln und im Öl 2 Min. braten.\nEier verquirlen, würzen, dazugeben und unter Rühren stocken lassen.\nTortilla kurz in der trockenen Pfanne erwärmen, Rührei und geriebenen Gouda daraufgeben und einrollen.","h"],
["Frühstück","Hummus-Gemüse-Brot mit Feta",385,14,"5 Min.",["100 g Vollkornbrot (2 Scheiben)","40 g Hummus","100 g Gurke","50 g Radieschen","20 g Feta","Kresse oder Schnittlauch"],"Brot mit Hummus bestreichen.\nGurke und Radieschen in dünne Scheiben schneiden und darauflegen.\nFeta darüberbröseln und mit Kresse oder Schnittlauch bestreuen.","h"],
["Frühstück","Avocado-Toast mit Hüttenkäse und Tomate",378,20,"5 Min.",["60 g Vollkorntoast (2 Scheiben)","½ Avocado","100 g Hüttenkäse","1 Tomate","Salz, Pfeffer, Chiliflocken"],"Toast rösten.\nAvocado mit einer Gabel zerdrücken, salzen und auf den Toast streichen.\nHüttenkäse und Tomatenscheiben darauf verteilen, mit Pfeffer und Chiliflocken würzen.","h"],
["Frühstück","Gemüse-Rührei mit Vollkornbrötchen",409,25,"10 Min.",["2 Eier (M)","50 ml Milch 1,5 %","½ Paprika","50 g Zucchini","1 Frühlingszwiebel","3 g Öl","1 Vollkornbrötchen","Salz, Pfeffer"],"Paprika und Zucchini klein würfeln, Frühlingszwiebel in Ringe schneiden.\nGemüse im Öl 3 Min. braten.\nEier mit Milch, Salz und Pfeffer verquirlen, darübergießen und unter Rühren stocken lassen.\nMit dem Brötchen servieren.","h"],
["Frühstück","Halloumi-Brötchen mit Tomate und Rucola",346,17,"8 Min.",["1 Vollkornbrötchen","40 g Halloumi","1 Tomate","20 g Rucola","3 g Öl"],"Halloumi in Scheiben schneiden und im Öl je Seite 1–2 Min. goldbraun braten.\nBrötchen aufschneiden und kurz toasten.\nMit Rucola, Tomatenscheiben und Halloumi belegen.","h"],
["Frühstück","Tofu-Rührei mit Spinat auf Toast",402,27,"10 Min.",["150 g Tofu natur","50 g Babyspinat","½ Zwiebel","5 g Öl","60 g Vollkorntoast (2 Scheiben)","Kurkuma, Salz, Pfeffer"],"Zwiebel fein würfeln und im Öl glasig braten.\nTofu mit einer Gabel zerbröseln, dazugeben und mit Kurkuma, Salz und Pfeffer 4 Min. braten.\nSpinat unterheben, bis er zusammenfällt.\nAuf dem gerösteten Toast servieren.","h"],
["Frühstück","Bohnen-Toast mit Spiegelei",389,22,"10 Min.",["120 g Weiße Bohnen (Dose, abgetropft)","100 g passierte Tomaten","60 g Vollkorntoast (2 Scheiben)","1 Ei (M)","3 g Öl","Paprikapulver, Salz, Pfeffer"],"Bohnen mit passierten Tomaten, Paprikapulver, Salz und Pfeffer 5 Min. köcheln.\nIn der Zwischenzeit das Ei im Öl als Spiegelei braten und den Toast rösten.\nBohnen auf den Toast geben und das Spiegelei darauflegen.","h"],
["Mittag","Spinat-Ricotta-Nudeln",453,22,"15 Min.",["80 g Vollkornnudeln (trocken)","100 g Babyspinat","60 g Ricotta","10 g vegetarischer Hartkäse (Parmesan-Art)","1 Knoblauchzehe","3 g Öl","Muskat, Salz, Pfeffer"],"Nudeln nach Packung in Salzwasser kochen, etwas Kochwasser auffangen.\nKnoblauch fein hacken und im Öl kurz anbraten, Spinat darin zusammenfallen lassen.\nRicotta und 3–4 EL Nudelwasser einrühren, mit Muskat, Salz und Pfeffer würzen.\nNudeln untermischen und mit Hartkäse bestreuen.","h"],
["Mittag","Gnocchi-Tomaten-Pfanne mit Mozzarella",556,22,"15 Min.",["200 g Gnocchi (Kühlregal)","150 g Cherrytomaten","50 g Babyspinat","60 g Mozzarella","5 g Öl","Basilikum, Salz, Pfeffer"],"Gnocchi im Öl 5–6 Min. rundum goldbraun braten.\nCherrytomaten halbieren, dazugeben und 3 Min. mitbraten.\nSpinat unterheben, salzen und pfeffern.\nMozzarella in Stücken darauf verteilen, mit Deckel 1–2 Min. schmelzen lassen und mit Basilikum servieren.","h"],
["Mittag","Käsespätzle light mit Salat",568,24,"20 Min.",["200 g Spätzle (Kühlregal)","40 g Emmentaler","½ Zwiebel","5 g Butter","80 g Blattsalat","1 TL Öl (5 g)","Essig, Salz, Pfeffer, Schnittlauch"],"Zwiebel in Ringe schneiden und in der Butter goldbraun braten, herausnehmen.\nSpätzle in derselben Pfanne 4 Min. braten.\nGeriebenen Emmentaler unterheben, bis er schmilzt, mit Pfeffer würzen.\nMit Röstzwiebeln und Schnittlauch bestreuen.\nSalat mit Öl, Essig, Salz und Pfeffer anmachen und dazu servieren.","h"],
["Mittag","Kartoffel-Lauch-Suppe mit Kichererbsen",438,15,"30 Min.",["250 g Kartoffeln","150 g Lauch","80 g Kichererbsen (Dose, abgetropft)","400 ml Gemüsebrühe","50 ml Kochsahne 15 %","5 g Öl","Majoran, Salz, Pfeffer"],"Kartoffeln schälen und würfeln, Lauch in Ringe schneiden.\nLauch im Öl 3 Min. andünsten, Kartoffeln und Brühe zugeben und 15 Min. köcheln.\nDie Hälfte grob pürieren, Kichererbsen und Sahne zugeben und 3 Min. erhitzen.\nMit Majoran, Salz und Pfeffer abschmecken.","h"],
["Mittag","Gemüse-Curry mit Kichererbsen und Reis",473,15,"25 Min.",["60 g Basmatireis (trocken)","100 g Kichererbsen (Dose, abgetropft)","100 ml Kokosmilch light","100 g Blumenkohl","½ Paprika","1 EL Rote Currypaste (15 g)","Ingwer, Salz"],"Reis nach Packung kochen.\nBlumenkohl in kleine Röschen teilen, Paprika würfeln.\nCurrypaste mit etwas Ingwer in einem Topf kurz anrösten, Kokosmilch und 50 ml Wasser angießen.\nGemüse zugeben und 8 Min. köcheln, Kichererbsen 2 Min. mit erhitzen.\nSalzen und mit dem Reis servieren.","h"],
["Mittag","Kürbissuppe mit Feta und Brot",380,15,"30 Min.",["300 g Hokkaido-Kürbis","1 Möhre","½ Zwiebel","400 ml Gemüsebrühe","50 ml Kokosmilch light","30 g Feta","50 g Vollkornbrot (1 Scheibe)","Ingwer, Salz, Pfeffer"],"Kürbis entkernen und mit Schale würfeln, Möhre und Zwiebel klein schneiden.\nGemüse mit der Brühe aufkochen und 20 Min. weich köcheln.\nKokosmilch zugeben, fein pürieren und mit Ingwer, Salz und Pfeffer abschmecken.\nMit zerbröseltem Feta bestreuen und mit dem Brot servieren.","h"],
["Mittag","Bulgur-Gemüse-Pfanne mit Joghurt",478,21,"25 Min.",["70 g Bulgur (trocken)","150 g Zucchini","½ Paprika","1 Tomate","100 g Naturjoghurt 1,5 %","30 g Feta","5 g Öl","Kreuzkümmel, Paprikapulver, Salz"],"Bulgur mit der doppelten Menge kochendem Salzwasser übergießen und 10 Min. quellen lassen.\nZucchini, Paprika und Tomate würfeln und im Öl 5 Min. braten, mit Kreuzkümmel und Paprikapulver würzen.\nBulgur untermischen und abschmecken.\nMit Joghurt und zerbröseltem Feta servieren.","h"],
["Mittag","Pesto-Nudeln mit Tomaten und Mozzarella",537,23,"15 Min.",["80 g Nudeln (trocken)","1 EL Pesto (grün)","150 g Cherrytomaten","60 g Mozzarella","20 g Rucola"],"Nudeln nach Packung kochen.\nCherrytomaten halbieren, Mozzarella würfeln.\nNudeln abgießen, sofort mit dem Pesto mischen.\nTomaten, Mozzarella und Rucola unterheben.","h"],
["Mittag","Erdnuss-Tofu mit Reisnudeln",575,29,"20 Min.",["60 g Reisnudeln (trocken)","125 g Tofu natur","1 EL Erdnussmus (15 g)","1 EL Sojasoße","100 g Brokkoli","1 Möhre","5 g Öl","Limette, Ingwer, Chili"],"Reisnudeln nach Packung einweichen oder kochen.\nTofu würfeln und im Öl rundum knusprig braten.\nBrokkoli in Röschen und Möhre in Streifen schneiden, 4 Min. mitbraten.\nErdnussmus mit Sojasoße, 3 EL Wasser, Ingwer und Limettensaft verrühren.\nNudeln und Soße untermischen, mit Chili abschmecken.","h"],
["Mittag","Linsen-Kartoffel-Eintopf",368,19,"35 Min.",["50 g Tellerlinsen (trocken)","200 g Kartoffeln","1 Möhre","100 g Lauch","1 EL Tomatenmark","400 ml Gemüsebrühe","Majoran, Essig, Salz, Pfeffer"],"Kartoffeln und Möhre würfeln, Lauch in Ringe schneiden.\nTomatenmark im Topf kurz anrösten, mit der Brühe ablöschen.\nLinsen und Gemüse zugeben und 25 Min. köcheln, bis alles weich ist.\nMit Majoran, einem Schuss Essig, Salz und Pfeffer abschmecken.","h"],
["Mittag","Polenta mit Tomaten-Bohnen-Ragout",454,19,"25 Min.",["60 g Polenta (Maisgrieß, trocken)","200 ml Gemüsebrühe","120 g Weiße Bohnen (Dose, abgetropft)","200 g gehackte Tomaten (Dose)","½ Zwiebel","10 g vegetarischer Hartkäse (Parmesan-Art)","5 g Öl","Oregano, Salz, Pfeffer"],"Zwiebel würfeln und im Öl glasig dünsten, Tomaten und Bohnen zugeben und 10 Min. köcheln, mit Oregano, Salz und Pfeffer würzen.\nBrühe aufkochen, Polenta einrühren und bei kleiner Hitze 5 Min. unter Rühren quellen lassen.\nHartkäse unter die Polenta rühren.\nPolenta mit dem Ragout anrichten.","h"],
["Mittag","Kartoffelpuffer mit Apfelmus",536,16,"30 Min.",["300 g Kartoffeln (roh)","1 Ei (M)","20 g Weizenmehl","½ Zwiebel","10 g Öl","150 g Apfelmus ohne Zucker","Salz, Muskat"],"Kartoffeln schälen und fein reiben, kräftig ausdrücken. Zwiebel fein reiben.\nMit Ei, Mehl, Salz und Muskat vermengen.\nÖl in einer beschichteten Pfanne erhitzen, flache Puffer je Seite 3–4 Min. knusprig braten.\nMit Apfelmus servieren.","h"],
["Mittag","Ratatouille mit Couscous und Feta",467,20,"30 Min.",["60 g Couscous (trocken)","150 g Aubergine","150 g Zucchini","½ Paprika","½ Zwiebel","200 g gehackte Tomaten (Dose)","30 g Feta","5 g Öl","Thymian, Rosmarin, Salz, Pfeffer"],"Aubergine, Zucchini, Paprika und Zwiebel würfeln und im Öl 5 Min. anbraten.\nTomaten und Kräuter zugeben und 15 Min. köcheln, abschmecken.\nCouscous mit der gleichen Menge kochendem Salzwasser übergießen und 5 Min. quellen lassen.\nRatatouille auf dem Couscous anrichten und mit Feta bestreuen.","h"],
["Mittag","Brokkoli-Nudelauflauf",489,27,"15 Min. + 15 Min. Ofen",["70 g Nudeln (trocken)","200 g Brokkoli","100 ml Milch 1,5 %","1 TL Speisestärke","30 g Gouda","Muskat, Salz, Pfeffer"],"Ofen auf 200 °C vorheizen. Nudeln kochen, Brokkoli in Röschen die letzten 4 Min. mitkochen, abgießen.\nMilch mit Stärke verrühren, unter Rühren aufkochen und mit Muskat, Salz und Pfeffer würzen.\nNudeln und Brokkoli in eine kleine Form geben, Soße darübergießen und mit geriebenem Gouda bestreuen.\n15 Min. goldbraun überbacken.","h"],
["Mittag","Süßkartoffel-Erdnuss-Eintopf",484,19,"30 Min.",["250 g Süßkartoffel","100 g Kichererbsen (Dose, abgetropft)","200 g gehackte Tomaten (Dose)","1 EL Erdnussmus (15 g)","50 g Babyspinat","300 ml Gemüsebrühe","Ingwer, Kreuzkümmel, Salz"],"Süßkartoffel schälen und würfeln.\nMit Tomaten, Brühe, Ingwer und Kreuzkümmel aufkochen und 15 Min. köcheln.\nErdnussmus einrühren, Kichererbsen zugeben und 5 Min. weiterköcheln.\nSpinat unterheben und abschmecken.","h"],
["Mittag","Falafel-Bowl mit Joghurtsoße",586,24,"15 Min.",["4 Falafel","50 g Couscous (trocken)","100 g Gurke","1 Tomate","30 g Blattsalat","100 g Naturjoghurt 1,5 %","Minze, Knoblauch, Salz"],"Couscous mit der gleichen Menge kochendem Salzwasser übergießen und 5 Min. quellen lassen.\nFalafel nach Packung im Ofen oder in der Pfanne erwärmen.\nGurke und Tomate würfeln, Salat zupfen.\nJoghurt mit Minze, etwas Knoblauch und Salz verrühren.\nAlles in einer Schüssel anrichten.","h"],
["Mittag","Penne mit Ofengemüse und Feta",514,21,"10 Min. + 20 Min. Ofen",["80 g Nudeln (trocken)","150 g Zucchini","½ Paprika","½ rote Zwiebel","100 g Cherrytomaten","40 g Feta","5 g Öl","Oregano, Salz, Pfeffer"],"Ofen auf 220 °C vorheizen.\nZucchini, Paprika und Zwiebel in Stücke schneiden, mit Tomaten, Öl, Oregano, Salz und Pfeffer mischen.\nAuf einem Blech verteilen, Feta in die Mitte legen und 20 Min. backen.\nNudeln kochen und mit Gemüse und zerdrücktem Feta mischen.","h"],
["Mittag","Rote-Bete-Risotto mit Feta",447,13,"30 Min.",["75 g Risottoreis (trocken)","150 g Rote Bete (gekocht)","½ Zwiebel","300 ml Gemüsebrühe (heiß)","5 g Butter","30 g Feta","Thymian, Salz, Pfeffer"],"Zwiebel fein würfeln und in der Butter glasig dünsten.\nReis zugeben und kurz anschwitzen.\nNach und nach heiße Brühe angießen und unter Rühren 18 Min. garen.\nRote Bete würfeln, die Hälfte pürieren und beides unterrühren.\nAbschmecken und mit zerbröseltem Feta und Thymian servieren.","h"],
["Mittag","Spitzkohl-Kartoffel-Pfanne mit Räuchertofu",523,26,"25 Min.",["250 g Kartoffeln","200 g Spitzkohl","100 g Räuchertofu","½ Zwiebel","50 ml Kochsahne 15 %","5 g Öl","Kümmel, Salz, Pfeffer"],"Kartoffeln würfeln und in Salzwasser 10 Min. vorkochen.\nRäuchertofu würfeln und im Öl knusprig braten, Zwiebel kurz mitbraten.\nSpitzkohl in Streifen schneiden, mit den Kartoffeln zugeben und 6 Min. braten.\nSahne einrühren, mit Kümmel, Salz und Pfeffer würzen.","h"],
["Mittag","Tomatensuppe mit Mozzarella-Brot",511,23,"20 Min.",["400 g gehackte Tomaten (Dose)","½ Zwiebel","200 ml Gemüsebrühe","5 g Öl","100 g Vollkornbrot (2 Scheiben)","60 g Mozzarella","Basilikum, Salz, Pfeffer, 1 Prise Zucker"],"Zwiebel würfeln und im Öl glasig dünsten.\nTomaten und Brühe zugeben, 10 Min. köcheln, pürieren und mit Salz, Pfeffer und Zucker abschmecken.\nBrot mit Mozzarella belegen und im Ofen oder in der Pfanne mit Deckel überbacken, bis der Käse schmilzt.\nSuppe mit Basilikum und dem Brot servieren.","h"],
["Abend","Gefüllte Zucchini mit Couscous und Feta",365,17,"15 Min. + 20 Min. Ofen",["300 g Zucchini","40 g Couscous (trocken)","1 Tomate","40 g Feta","5 g Öl","Oregano, Salz, Pfeffer"],"Ofen auf 200 °C vorheizen. Zucchini längs halbieren und aushöhlen, das Fruchtfleisch hacken.\nCouscous mit der gleichen Menge kochendem Wasser 5 Min. quellen lassen.\nZucchinifleisch und Tomate würfeln, im Öl 3 Min. braten, mit Couscous mischen und würzen.\nIn die Zucchinihälften füllen, Feta darüberbröseln und 20 Min. backen.","h"],
["Abend","Ofen-Aubergine mit Joghurt-Tahin und Kichererbsen",405,17,"10 Min. + 25 Min. Ofen",["300 g Aubergine","10 g Öl","100 g Kichererbsen (Dose, abgetropft)","100 g Naturjoghurt 1,5 %","1 EL Tahin","Petersilie, Zitrone, Salz, Kreuzkümmel"],"Ofen auf 220 °C vorheizen. Aubergine längs halbieren, das Fruchtfleisch rautenförmig einschneiden, mit Öl bestreichen und salzen.\nMit den Kichererbsen (mit Kreuzkümmel gewürzt) auf einem Blech 25 Min. backen.\nJoghurt mit Tahin, Zitronensaft und Salz verrühren.\nAubergine mit Joghurt-Tahin, Kichererbsen und Petersilie anrichten.","h"],
["Abend","Blumenkohl-Steak mit Linsensalat",349,23,"15 Min. + 25 Min. Ofen",["300 g Blumenkohl","5 g Öl","40 g Tellerlinsen (trocken)","1 Tomate","30 g Feta","Petersilie, Essig, Paprikapulver, Salz"],"Ofen auf 220 °C vorheizen. Blumenkohl in 2 dicke Scheiben schneiden, mit Öl, Paprikapulver und Salz einreiben und 25 Min. backen, einmal wenden.\nLinsen in Wasser 20 Min. bissfest kochen und abgießen.\nTomate würfeln, mit Linsen, Petersilie, Essig und Salz mischen.\nBlumenkohl auf dem Linsensalat anrichten und mit Feta bestreuen.","h"],
["Abend","Quesadilla mit Bohnen und Mais",421,21,"15 Min.",["1 Vollkorn-Tortilla","60 g Kidneybohnen (Dose, abgetropft)","40 g Mais (Dose)","½ Paprika","30 g Gouda","50 g Naturjoghurt 1,5 %","Kreuzkümmel, Chili, Salz"],"Bohnen grob zerdrücken, Paprika fein würfeln, mit Mais und Gewürzen mischen.\nAuf eine Hälfte der Tortilla geben, mit geriebenem Gouda bestreuen und zuklappen.\nIn einer trockenen Pfanne je Seite 2–3 Min. knusprig braten.\nIn Stücke schneiden und mit Joghurt zum Dippen servieren.","h"],
["Abend","Tofu-Gemüse-Spieße mit Erdnussdip und Reis",616,33,"25 Min.",["150 g Tofu natur","½ Paprika","150 g Zucchini","60 g Reis (trocken)","1 EL Erdnussmus (15 g)","1 EL Sojasoße","5 g Öl","Limette, Knoblauch"],"Reis nach Packung kochen.\nTofu, Paprika und Zucchini in Würfel schneiden und abwechselnd auf Spieße stecken.\nMit Öl bestreichen und in der Pfanne oder auf dem Grill rundum 8 Min. braten.\nErdnussmus mit Sojasoße, 2 EL warmem Wasser, Knoblauch und Limette verrühren.\nSpieße mit Reis und Dip servieren.","h"],
["Abend","Linsensalat mit Ziegenfrischkäse und Walnüssen",424,20,"25 Min.",["50 g Tellerlinsen (trocken)","1 Möhre","30 g Rucola","30 g Ziegenfrischkäse","10 g Walnüsse","5 g Öl","1 TL Honig (7 g)","Essig, Senf, Salz, Pfeffer"],"Linsen in Wasser 20 Min. bissfest kochen, abgießen und abkühlen lassen.\nMöhre raspeln.\nÖl, Essig, Honig, Senf, Salz und Pfeffer verrühren und mit Linsen und Möhre mischen.\nAuf Rucola anrichten, Ziegenkäse und gehackte Walnüsse darüber verteilen.","h"],
["Abend","Fladenbrot-Pizza mit Gemüse",408,21,"10 Min. + 10 Min. Ofen",["80 g Fladenbrot","50 g passierte Tomaten","60 g Mozzarella","½ Paprika","50 g Zucchini","20 g Rucola","Oregano, Salz"],"Ofen auf 220 °C vorheizen.\nFladenbrot mit passierten Tomaten bestreichen und mit Oregano und Salz würzen.\nPaprika und Zucchini in dünne Scheiben schneiden, darauflegen und mit Mozzarella belegen.\n10 Min. backen und mit Rucola belegt servieren.","h"],
["Abend","Kürbis-Kichererbsen-Curry",482,16,"30 Min.",["200 g Hokkaido-Kürbis","100 g Kichererbsen (Dose, abgetropft)","100 ml Kokosmilch light","50 g Babyspinat","1 EL Rote Currypaste (15 g)","50 g Basmatireis (trocken)","Ingwer, Salz"],"Reis nach Packung kochen.\nKürbis würfeln.\nCurrypaste mit Ingwer anrösten, Kokosmilch und 100 ml Wasser zugeben, Kürbis darin 12 Min. köcheln.\nKichererbsen zugeben, Spinat unterheben und salzen.\nMit Reis servieren.","h"],
["Abend","Rote-Linsen-Suppe mit Kokos",391,17,"25 Min.",["50 g Rote Linsen (trocken)","1 Möhre","½ Zwiebel","100 ml Kokosmilch light","300 ml Gemüsebrühe","50 g Vollkornbrot (1 Scheibe)","Currypulver, Zitrone, Salz"],"Zwiebel und Möhre würfeln und kurz andünsten, Currypulver zugeben.\nLinsen, Brühe und Kokosmilch zugeben und 15 Min. köcheln, bis die Linsen zerfallen.\nFein pürieren, mit Zitronensaft und Salz abschmecken.\nMit dem Brot servieren.","h"],
["Abend","Weiße-Bohnen-Shakshuka",431,29,"20 Min.",["120 g Weiße Bohnen (Dose, abgetropft)","200 g gehackte Tomaten (Dose)","½ Paprika","2 Eier (M)","20 g Feta","5 g Öl","Kreuzkümmel, Paprikapulver, Salz"],"Paprika würfeln und im Öl 3 Min. braten.\nTomaten, Bohnen und Gewürze zugeben und 5 Min. köcheln.\nZwei Mulden formen, die Eier hineinschlagen und mit Deckel 6–8 Min. stocken lassen.\nMit Feta bestreuen.","h"],
["Abend","Caprese-Salat mit Kichererbsen",611,34,"10 Min.",["125 g Mozzarella","2 Tomaten","100 g Kichererbsen (Dose, abgetropft)","5 g Öl","50 g Vollkornbrot (1 Scheibe)","Basilikum, Balsamico, Salz, Pfeffer"],"Tomaten und Mozzarella in Scheiben schneiden und auf einem Teller auslegen.\nKichererbsen darüber verteilen.\nMit Öl, Balsamico, Salz und Pfeffer beträufeln und mit Basilikum bestreuen.\nMit dem Brot servieren.","h"],
["Abend","Asia-Nudelpfanne mit Tofu",506,25,"20 Min.",["60 g Reisnudeln (trocken)","125 g Tofu natur","150 g Wokgemüse (TK)","1 EL Sojasoße","5 g Öl","5 g Sesam","Ingwer, Knoblauch, Chili"],"Reisnudeln nach Packung zubereiten.\nTofu würfeln und im Öl knusprig braten.\nWokgemüse mit Ingwer und Knoblauch zugeben und 5 Min. braten.\nNudeln und Sojasoße untermischen, mit Chili würzen und mit Sesam bestreuen.","h"],
["Abend","Bulgur-Salat mit Feta (Tabouleh)",384,16,"20 Min.",["60 g Bulgur (trocken)","1 Tomate","100 g Gurke","40 g Feta","5 g Öl","Petersilie, Minze, Zitrone, Salz"],"Bulgur mit der doppelten Menge kochendem Wasser übergießen und 10 Min. quellen lassen, abkühlen lassen.\nTomate und Gurke klein würfeln, Kräuter hacken.\nAlles mit Öl, Zitronensaft und Salz mischen.\nFeta darüberbröseln.","h"],
["Abend","Gefüllte Süßkartoffel mit Bohnen und Mais",431,16,"10 Min. + 40 Min. Ofen",["250 g Süßkartoffel","60 g Kidneybohnen (Dose, abgetropft)","40 g Mais (Dose)","50 g Saure Sahne","20 g Gouda","Paprikapulver, Kreuzkümmel, Salz"],"Ofen auf 200 °C vorheizen. Süßkartoffel einstechen und 35–40 Min. backen, bis sie weich ist.\nBohnen und Mais mit den Gewürzen mischen.\nSüßkartoffel längs aufschneiden, das Innere etwas zerdrücken, Bohnen-Mais-Mischung hineingeben und mit Gouda bestreuen.\n5 Min. überbacken und mit saurer Sahne servieren.","h"],
["Abend","Zucchini-Puffer mit Joghurt-Dip",444,24,"25 Min.",["250 g Zucchini","1 Ei (M)","30 g Weizenmehl","20 g vegetarischer Hartkäse (Parmesan-Art)","10 g Öl","100 g Naturjoghurt 1,5 %","Knoblauch, Salz, Pfeffer"],"Zucchini grob raspeln, salzen, 5 Min. ziehen lassen und kräftig ausdrücken.\nMit Ei, Mehl, Hartkäse und Pfeffer verrühren.\nIm Öl kleine Puffer je Seite 3 Min. goldbraun braten.\nJoghurt mit Knoblauch und Salz verrühren und dazu servieren.","h"],
["Abend","Kartoffel-Bohnen-Salat mit Ei",401,22,"30 Min.",["200 g Kartoffeln","150 g Grüne Bohnen","2 Eier (M)","½ Zwiebel","5 g Öl","Essig, Senf, Salz, Pfeffer, Petersilie"],"Kartoffeln mit Schale 20 Min. kochen, pellen und in Scheiben schneiden.\nBohnen 8 Min. in Salzwasser garen, Eier 9 Min. hart kochen.\nZwiebel fein würfeln und mit Öl, Essig, Senf, Salz und Pfeffer zu einem Dressing verrühren.\nKartoffeln und Bohnen untermischen, mit geviertelten Eiern und Petersilie servieren.","h"],
["Abend","Spinat-Pfannkuchen mit Feta",438,25,"20 Min.",["40 g Weizenmehl","1 Ei (M)","100 ml Milch 1,5 %","100 g Babyspinat","40 g Feta","5 g Öl","Muskat, Salz, Pfeffer"],"Mehl, Ei, Milch und Salz zu einem glatten Teig verrühren und 5 Min. quellen lassen.\nSpinat in einer Pfanne zusammenfallen lassen, mit Muskat, Salz und Pfeffer würzen.\nIm Öl 2 dünne Pfannkuchen backen.\nMit Spinat und zerbröseltem Feta füllen und zusammenklappen.","h"],
["Abend","Spitzkohl-Nudeln mit Frischkäse",434,16,"20 Min.",["70 g Nudeln (trocken)","200 g Spitzkohl","½ Zwiebel","50 g Frischkäse leicht","5 g Öl","Kümmel, Muskat, Salz, Pfeffer"],"Nudeln nach Packung kochen, etwas Kochwasser auffangen.\nZwiebel und Spitzkohl in Streifen schneiden und im Öl 6 Min. braten.\nFrischkäse und 3–4 EL Nudelwasser einrühren, mit Kümmel, Muskat, Salz und Pfeffer würzen.\nNudeln untermischen.","h"],
["Abend","Auberginen-Parmigiana light",363,22,"15 Min. + 25 Min. Ofen",["300 g Aubergine","200 g passierte Tomaten","60 g Mozzarella","15 g vegetarischer Hartkäse (Parmesan-Art)","5 g Öl","Basilikum, Oregano, Salz, Pfeffer"],"Ofen auf 200 °C vorheizen. Aubergine in Scheiben schneiden, mit Öl bestreichen und in einer Pfanne oder im Ofen von beiden Seiten anbräunen.\nTomaten mit Oregano, Salz und Pfeffer würzen.\nAuberginen, Tomatensoße und Mozzarella in einer kleinen Form schichten, mit Hartkäse bestreuen.\n25 Min. backen und mit Basilikum servieren.","h"],
["Abend","Minestrone mit weißen Bohnen",400,20,"35 Min.",["100 g Kartoffeln","1 Möhre","100 g Zucchini","100 g Lauch","80 g Weiße Bohnen (Dose, abgetropft)","200 g gehackte Tomaten (Dose)","30 g Nudeln (trocken)","400 ml Gemüsebrühe","10 g vegetarischer Hartkäse (Parmesan-Art)","Basilikum, Salz, Pfeffer"],"Kartoffeln, Möhre und Zucchini würfeln, Lauch in Ringe schneiden.\nGemüse mit Tomaten und Brühe aufkochen und 15 Min. köcheln.\nNudeln und Bohnen zugeben und weitere 8–10 Min. köcheln.\nAbschmecken und mit Hartkäse und Basilikum servieren.","h"]];
